    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Find diagonal runs of at least two identical non-background cells.
    runs = []
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v == bg:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == v:
                    continue
                cells = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == v:
                    cells.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(cells) >= 2:
                    runs.append((cells, v, dr, dc))

    if not runs:
        return [row[:] for row in grid]

    # On a diagonal containing successive runs of different colors, extend
    # the run at the lower end (e.g. 0,0,7,7 becomes an extension of 7).
    def line_key(cell, dr, dc):
        r, c = cell
        return c - r if dc == 1 else c + r

    selected = None
    for run in runs:
        cells, color, dr, dc = run
        key = line_key(cells[0], dr, dc)
        same_line = [x for x in runs
                     if x[2:] == (dr, dc) and line_key(x[0][0], dr, dc) == key]
        if len(same_line) > 1:
            selected = max(same_line, key=lambda x: max(p[0] for p in x[0]))
            break
    if selected is None:
        selected = runs[0]

    cells, color, dr, dc = selected
    # Continue downward from the lower endpoint of the run.
    r, c = max(cells, key=lambda p: p[0])
    r, c = r + dr, c + dc
    out = [row[:] for row in grid]
    while 0 <= r < h and 0 <= c < w:
        if out[r][c] == bg:
            out[r][c] = color
        r += dr
        c += dc
    return out
